input.dsl:
workspace "Order Service" "Architecture of the Order Service" {
    model {
        customer = person "Customer" "Places and tracks orders"
        support = person "Support Agent" "Assists customers and manages orders"

        payments = softwareSystem "Payment Gateway" "Processes card payments" "External"
        inventory = softwareSystem "Inventory Service" "Tracks stock levels" "External"

        orders = softwareSystem "Order Service" "Manages the order lifecycle" {
            web = container "Web App" "Customer-facing storefront" "React" "Web"
            api = container "Order API" "REST API for order operations" "Node.js" {
                orderController = component "Order Controller" "Handles order HTTP requests" "Express"
                orderService = component "Order Service" "Business logic for orders" "TypeScript"
                orderRepository = component "Order Repository" "Persists orders" "TypeScript"
            }
            worker = container "Order Worker" "Processes orders asynchronously" "Node.js"
            db = container "Order Database" "Stores order data" "PostgreSQL" "Database"
        }

        customer -> web "Browses and places orders" "HTTPS"
        support -> api "Manages orders" "HTTPS/JSON"
        web -> api "Submits orders" "HTTPS/JSON"
        api -> db "Reads and writes orders" "SQL"
        api -> payments "Charges cards" "HTTPS/JSON"
        api -> worker "Enqueues order events" "AMQP" "Async"
        worker -> inventory "Reserves stock" "AMQP" "Async"
        worker -> db "Updates order status" "SQL"
        orderController -> orderService "Validates and delegates" "In-process"
        orderService -> orderRepository "Persists order" "In-process"
    }

    views {
        systemContext orders "SystemContext" "Shows the Order Service and its actors" {
            autoLayout
            include *
        }

        container orders "Containers" "Shows the containers of the Order Service" {
            autoLayout
            include *
        }

        component api "Components" "Shows the components of the Order API" {
            autoLayout
            include *
        }

        dynamic * "PlaceOrder" "Shows the order placement flow" {
            customer -> orders "Places an order" "HTTPS"
            orders -> payments "Charges the card" "HTTPS/JSON"
            orders -> inventory "Reserves stock" "AMQP"
            autoLayout
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Component" {
                background #85BBF0
                color #000000
            }
            element "Database" {
                shape Cylinder
            }
            element "Web" {
                shape WebBrowser
            }
            relationship "Async" {
                style dashed
            }
        }
    }
}

